아래는 EPPlus를 사용하여 엑셀 파일에서 테이블 데이터를 읽고, `ExcelData` 클래스의 리스트로 매핑하며, 각 객체의 속성을 출력하는 완성된 코드입니다.

```csharp
using OfficeOpenXml;
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;

public class ExcelData
{
    public string Id { get; set; }
    public string Name { get; set; }
    public string Gender { get; set; }
}

public class ExcelReader
{
    public static List<ExcelData> ReadExcelData(string filePath)
    {
        var package = new ExcelPackage(new FileInfo(filePath));
        ExcelWorksheet sheet = package.Workbook.Worksheets[1];

        // Assuming the headers are in the first row
        int startRow = 2; // Start at the second row as the first row is the header
        int totalRows = sheet.Dimension.End.Row;

        // Read the headers and create a dictionary to map column index to property name
        var headers = sheet.Row(1).Select(cell => cell.Text).ToArray();
        var columnMapping = headers.Select((header, index) => new { Header = header, Index = index })
                                     .ToDictionary(x => x.Index, x => x.Header);

        // Create a list to hold the data
        List<ExcelData> excelDataList = new List<ExcelData>();

        // Loop through all rows starting from the second row
        for (int row = startRow; row <= totalRows; row++)
        {
            // Create a new ExcelData object
            ExcelData data = new ExcelData();

            // Loop through each column in the row
            foreach (var cell in sheet.Row(row).Select((cell, index) => new { Cell = cell, Index = index }))
            {
                // Map the column index to the property name and set the value
                switch (columnMapping[cell.Index])
                {
                    case "Id":
                        data.Id = cell.Cell.Text;
                        break;
                    case "Name":
                        data.Name = cell.Cell.Text;
                        break;
                    case "Gender":
                        data.Gender = cell.Cell.Text;
                        break;
                }
            }

            // Add the ExcelData object to the list
            excelDataList.Add(data);
        }

        return excelDataList;
    }

    public static void PrintExcelData(List<ExcelData> dataList)
    {
        foreach (var data in dataList)
        {
            Console.WriteLine($"Id: {data.Id}, Name: {data.Name}, Gender: {data.Gender}");
        }
    }
}

class Program
{
    static void Main(string[] args)
    {
        string filePath = @"C:\ExcelFile.xlsx";
        List<ExcelData> excelDataList = ExcelReader.ReadExcelData(filePath);
        ExcelReader.PrintExcelData(excelDataList);
    }
}
```

